                        <table>
                          <thead>
                            <tr>
                              <th>Period</th>
                              <th>Return</th>
                              <th>Trades</th>
                              <th>Win Rate</th>
                              <th>Sharpe</th>
                              <th>Max DD</th>
                            </tr>
                          </thead>
                          <tbody>
                            {backtestResults.period_results.map((period: any, index: number) => (
                              <tr key={index}>
                                <td>{period.start_date} - {period.end_date}</td>
