                                  {formatCurrency(period.total_return)}
                                </td>
                                <td>{period.total_trades}</td>
                                <td>{(period.win_rate * 100).toFixed(1)}%</td>
                                <td>{period.sharpe_ratio?.toFixed(2) || 'N/A'}</td>
                                <td className="negative">{(period.max_drawdown * 100).toFixed(2)}%</td>
                              </tr>
                            ))}
