              </div>
              <div className="filter-info">
                <small>
                  Filters: ≥${filterSettings.minAvgProfit} avg profit, 
                  ≥{filterSettings.minWinRate}% win rate, 
                  ≥{filterSettings.minTrades} trades per slot
                </small>
